window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-60f610dfd18344b9"]={"versions": [{"id": "FIG-60f610dfd18344b9", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Entwurfsmusterdiagramm für die AUTOSAR Chassis-Domäne. Das Schaubild stellt die Gegenüberstellung von logischem Steuerungsfluss (Command Flow) und konkretem AUTOSAR-Signalfluss (Signal Flow) anhand zweier interagierender Software-Komponenten (<code>SW-C 1</code> und <code>SW-C 2</code>) für Steuerbefehle (Command) und Rückmeldungen (Feedback) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SW-C 1</code> und <code>SW-C 2</code>: AUTOSAR Software-Components.</li>\n<li>Ports:</li>\n<li>Command: P-Port an <code>SW-C 1</code>, R-Port an <code>SW-C 2</code> (Sender-Receiver-Kommunikation).</li>\n<li>Feedback: P-Port an <code>SW-C 2</code>, R-Port an <code>SW-C 1</code>.</li>\n<li>Signal- und Namenskonventionen:</li>\n<li>Command Flow (logisch): <code>!</code> für Command, <code>?</code> für Feedback von <code>SW-C 1</code> zu <code>SW-C 2</code>.</li>\n<li>Signal Flow (technisch): Signale mit Präfixen/Kürzeln <code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code> (Command-Richtung) bzw. <code>Cur</code>, <code>Act</code>, <code>Sts</code>, <code>Mod</code> (Feedback-Richtung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Command-Ablauf: Der logische Kontrollfluss initiiert eine Anweisung (<code>!</code>) von <code>SW-C 1</code> an <code>SW-C 2</code>. Dies entspricht einem Signalfluss von P-Port (<code>SW-C 1</code>) zu R-Port (<code>SW-C 2</code>), transportiert über Sender-Receiver-Kommunikation (<code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code>).</li>\n<li>Feedback-Ablauf: Der logische Kontrollfluss stellt eine Abfrage oder Informationsanforderung (<code>?</code>) von <code>SW-C 1</code> in Richtung <code>SW-C 2</code> dar. Der tatsächliche Daten-/Signalfluss verläuft gegenläufig von <code>SW-C 2</code> (P-Port) zu <code>SW-C 1</code> (R-Port) und liefert Status- und Istwerte (<code>Cur</code>, <code>Act</code>, <code>Sts</code>, <code>Mod</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterung der Signal- und Namenskonventionen für AUTOSAR Sender-Receiver-Schnittstellen in Chassis-Anwendungen. Software-Architekten und Entwickler müssen beachten, dass Steuerungsfluss und physikalischer Datenfluss bei Feedback-Mechanismen entgegengesetzt gerichtet sind. Die Kürzel dienen als Naming-Guide für Signale und Datenelemente im Software Component Description Modell.</p>"}, {"id": "FIG-55c136db6091650a", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Entwurfsmusterdiagramm für die AUTOSAR Chassis-Domäne. Das Schaubild stellt die Gegenüberstellung von logischem Kontrollfluss (Control Flow) und konkretem AUTOSAR-Signalfluss (Signal Flow) anhand zweier interagierender Software-Komponenten (<code>SW-C 1</code> und <code>SW-C 2</code>) für Steuerbefehle (Command) und Rückmeldungen (Feedback) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SW-C 1</code> und <code>SW-C 2</code>: AUTOSAR Software-Components.</li>\n<li>Ports:</li>\n<li>Command: P-Port an <code>SW-C 1</code>, R-Port an <code>SW-C 2</code> (Sender-Receiver-Kommunikation).</li>\n<li>Feedback: P-Port an <code>SW-C 2</code>, R-Port an <code>SW-C 1</code>.</li>\n<li>Signal- und Namenskonventionen:</li>\n<li>Control Flow (logisch): <code>!</code> für Command, <code>?</code> für Feedback von <code>SW-C 1</code> zu <code>SW-C 2</code>.</li>\n<li>Signal Flow (technisch): Signale mit Präfixen/Kürzeln <code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code> (Command-Richtung) bzw. <code>Consold</code>, <code>St</code>, <code>Mod</code> (Feedback-Richtung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Command-Ablauf: Der logische Kontrollfluss initiiert eine Anweisung (<code>!</code>) von <code>SW-C 1</code> an <code>SW-C 2</code>. Dies entspricht einem Signalfluss von P-Port (<code>SW-C 1</code>) zu R-Port (<code>SW-C 2</code>), transportiert über Sender-Receiver-Kommunikation (<code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code>).</li>\n<li>Feedback-Ablauf: Der logische Kontrollfluss stellt eine Statusabfrage oder Informationsanforderung (<code>?</code>) von <code>SW-C 1</code> in Richtung <code>SW-C 2</code> dar. Der tatsächliche Daten-/Signalfluss verläuft gegenläufig von <code>SW-C 2</code> (P-Port) zu <code>SW-C 1</code> (R-Port) und liefert konsolidierte Zustands- und Moduswerte (<code>Consold</code>, <code>St</code>, <code>Mod</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterung der Signal- und Namenskonventionen für AUTOSAR Sender-Receiver-Schnittstellen in Chassis-Anwendungen. Software-Architekten und Entwickler müssen beachten, dass Kontrollfluss und physikalischer Datenfluss bei Feedback-Mechanismen entgegengesetzt gerichtet sind. Die Kürzel dienen als Naming-Guide für Signale und Datenelemente im Software Component Description Modell.</p>"}, {"id": "FIG-4755fc18c06299c0", "releases": ["R23-11", "R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Entwurfsmusterdiagramm für die AUTOSAR Chassis-Domäne. Das Schaubild stellt die Gegenüberstellung von logischem Kontrollfluss (Control Flow) und konkretem AUTOSAR-Signalfluss (Signal Flow) anhand zweier interagierender Software-Komponenten (<code>SW-C 1</code> und <code>SW-C 2</code>) für Steuerbefehle (Command) und Rückmeldungen (Feedback) dar.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>SW-C 1</code> und <code>SW-C 2</code>: AUTOSAR Software-Components.</li>\n<li>Ports:</li>\n<li>Command: P-Port an <code>SW-C 1</code>, R-Port an <code>SW-C 2</code> (Sender-Receiver-Kommunikation).</li>\n<li>Feedback: P-Port an <code>SW-C 2</code>, R-Port an <code>SW-C 1</code>.</li>\n<li>Signal- und Namenskonventionen:</li>\n<li>Control Flow (logisch): <code>!</code> für Command, <code>?</code> für Feedback von <code>SW-C 1</code> zu <code>SW-C 2</code>.</li>\n<li>Signal Flow (technisch): Signale mit Präfixen/Kürzeln <code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code> (Command-Richtung) bzw. <code>Consold</code>, <code>St</code>, <code>Mod</code> (Feedback-Richtung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Command-Ablauf: Der logische Kontrollfluss initiiert eine Anweisung (<code>!</code>) von <code>SW-C 1</code> an <code>SW-C 2</code>. Dies entspricht einem Signalfluss von P-Port (<code>SW-C 1</code>) zu R-Port (<code>SW-C 2</code>), transportiert über Sender-Receiver-Kommunikation (<code>Cmd</code>, <code>Req</code>, <code>Tar</code>, <code>Mod</code>).</li>\n<li>Feedback-Ablauf: Der logische Kontrollfluss stellt eine Statusabfrage oder Informationsanforderung (<code>?</code>) von <code>SW-C 1</code> in Richtung <code>SW-C 2</code> dar. Der tatsächliche Daten-/Signalfluss verläuft gegenläufig von <code>SW-C 2</code> (P-Port) zu <code>SW-C 1</code> (R-Port) und liefert konsolidierte Zustands- und Moduswerte (<code>Consold</code>, <code>St</code>, <code>Mod</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Erläuterung der Signal- und Namenskonventionen für AUTOSAR Sender-Receiver-Schnittstellen in Chassis-Anwendungen. Software-Architekten und Entwickler müssen beachten, dass Kontrollfluss und physikalischer Datenfluss bei Feedback-Mechanismen entgegengesetzt gerichtet sind. Die Kürzel dienen als Naming-Guide für Signale und Datenelemente im Software Component Description Modell.</p>"}], "trans": [{"from": "FIG-60f610dfd18344b9", "to": "FIG-55c136db6091650a", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Spaltenüberschrift links von <code>Command Flow</code> in <code>Control Flow</code> umbenannt.</li>\n<li>Signalfluss-Präfixe bei Feedback-Signalen von <code>Cur</code>, <code>Act</code>, <code>Sts</code>, <code>Mod</code> zu <code>Consold</code>, <code>St</code>, <code>Mod</code> geändert.</li>\n</ul>"}, {"from": "FIG-55c136db6091650a", "to": "FIG-4755fc18c06299c0", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
